#include <string>
#include <string_view>
#include <utility>
#include <vector>

class INotifier
{
public:
    virtual ~INotifier() = default;
    virtual void send(std::string_view message) = 0;
};

class ListNotifier : public INotifier
{
public:
    void send(std::string_view message) override { m_sent.emplace_back(message); }
    const std::vector<std::string>& sent() const { return m_sent; }

private:
    std::vector<std::string> m_sent{};
};

class PrefixNotifier : public INotifier
{
public:
    PrefixNotifier(std::string prefix, INotifier& next) : m_prefix{ std::move(prefix) }, m_next{ next } {}
    void send(std::string_view message) override { m_next.send(m_prefix + std::string{ message }); }

private:
    std::string m_prefix{};
    INotifier& m_next;
};

class MultiNotifier : public INotifier
{
public:
    void add(INotifier& target) { m_targets.push_back(&target); }

    void send(std::string_view message) override
    {
        for (INotifier* target : m_targets)
        {
            target->send(message);
        }
    }

private:
    std::vector<INotifier*> m_targets{};
};

unitTests:
using Lines = std::vector<std::string>;
static_assert(std::is_abstract_v<INotifier>);

TEST("list") { ListNotifier l{}; l.send("a"); l.send("b"); CHECK_EQ(l.sent(), (Lines{ "a", "b" })); }
TEST("prefix decorates") { ListNotifier l{}; PrefixNotifier p{ "[warn] ", l }; p.send("disk full"); CHECK_EQ(l.sent(), (Lines{ "[warn] disk full" })); }
TEST("multi fans out") { ListNotifier a{}, b{}; MultiNotifier m{}; m.add(a); m.add(b); m.send("hi"); CHECK_EQ(a.sent(), (Lines{ "hi" })); CHECK_EQ(b.sent(), (Lines{ "hi" })); }
TEST("they nest") {
    ListNotifier console{}, file{};
    PrefixNotifier tagged{ "app: ", console };
    MultiNotifier both{};
    both.add(tagged);
    both.add(file);
    PrefixNotifier outer{ "! ", both };
    INotifier& n{ outer };
    n.send("started");
    CHECK_EQ(console.sent(), (Lines{ "app: ! started" }));
    CHECK_EQ(file.sent(), (Lines{ "! started" }));
}

